contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 betLimit, uint256 difficulty) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (betLimit)); require(betLimit <= 1000000000000000000000000000000);
        require(address(this).balance >= betLimit);
        require(betLimit > 0);
        require(difficulty > 0);

        c.OpenToThePublic(); if (__ESBMC_reverted()) return;
        c.AdjustDifficulty(difficulty); if (__ESBMC_reverted()) return;
        c.AdjustBetAmounts(betLimit); if (__ESBMC_reverted()) return;
        c.wager{value: betLimit}(); if (__ESBMC_reverted()) return;

        bool before = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        c.play(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        bool stillWagered = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;

        assert(before && (reverted || !stillWagered));
    }

    receive() external payable {}
}

