    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 betLimit, uint256 difficulty) internal {
        betLimit = bound(betLimit, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= betLimit);
        vm.assume(betLimit > 0);
        vm.assume(difficulty > 0);
        try c.OpenToThePublic() {} catch { return; }
        try c.AdjustDifficulty(difficulty) {} catch { return; }
        try c.AdjustBetAmounts(betLimit) {} catch { return; }
        try c.wager{value: betLimit}() {} catch { return; }
        bool before;
        try c.hasPlayerWagered(address(this)) returns (bool __r) { before = __r; } catch { return; }
        bool reverted;
        try c.play() {
            reverted = false;
        } catch {
            reverted = true;
        }
        bool stillWagered;
        try c.hasPlayerWagered(address(this)) returns (bool __r) { stillWagered = __r; } catch { return; }
        assertTrue(before && (reverted || !stillWagered));
    }

    function testFuzz_run(uint256 betLimit, uint256 difficulty) public {
